document.addEventListener("DOMContentLoaded",(()=>{const e=document.getElementById("loginForm"),t=document.getElementById("loginMessage"),n=document.getElementById("loginSubmit");e.addEventListener("submit",(async a=>{a.preventDefault();const o=e.email.value.trim(),s=e.password.value;if(t.className="form-message",t.textContent="",!o||!s)return t.className="form-message error",void(t.textContent="Enter your email and password to continue.");n.disabled=!0,n.textContent="Logging in...";try{await RotimaticApi.login({email:o,password:s}),window.location.href="dashboard.html"}catch(e){t.className="form-message error",t.textContent=401===e.status?"The email or password is incorrect.":e.status>=500?"We could not reach your account. Please try again.":e.message}finally{n.disabled=!1,n.textContent="Log in"}}))}));